// ==UserScript==
// @name        darflen freaky mode
// @namespace   Violentmonkey Scripts
// @icon data:image/png;base64,
// @version     1.0.2-2026-10-11
//
// @match       https://darflen.com/*
// @grant       GM_addStyle
//
// @author      fungifungus
// @description become freaky
// ==/UserScript==
(function() {
    'use strict';
    const website = document.querySelector("#website");
    if (localStorage.getItem("fungifungus-freaky")===null) {
        localStorage.setItem("fungifungus-freaky", "true");
    };
    let toggle;
    function togg(){
        toggle = localStorage.getItem("fungifungus-freaky") === "true";
    };
    togg();
    GM_addStyle(`
    @font-face {
      font-family: "PapyrusPlain";
      src: url("https://fungi-fungus.github.io/PAPYRUS.TTF") format("truetype");
    }`)
    let freakystyle, vignette1, vignette2, observer;
    let logo = website.querySelector("#nav-logo > img");
    function freak() {
        if (observer) return;
        freakystyle = GM_addStyle(`
        *, ::after, ::before {
          animation-duration: 2s !important;
          transition-duration: 2s !important;
        }
        :root {
          --font-sans-serif:Papyrus,PapyrusPlain,fantasy
        }
        .fungifungus-freaky::after {
          content:"👅"
        }
        .fungifungus-vignette1 {
          position:fixed;
          top:0;
          left:0;
          width:100%;
          height:100%;
          box-shadow:-100px -160px 600px 0 rgb(247 23 69 / .4) inset;
          z-index:99999;
          pointer-events:none
        }
        .fungifungus-vignette2 {
          position:fixed;
          top:0;
          left:0;
          width:100%;
          height:100%;
          box-shadow:150px 200px 600px 0 rgb(211 90 176 / .6) inset;
          z-index:99999;
          pointer-events:none
        }
        `)
        vignette1 = document.createElement("div");
        vignette2 = document.createElement("div");
        vignette1.classList.add("fungifungus-vignette1");
        vignette2.classList.add("fungifungus-vignette2");
        website.prepend(vignette1);
        website.prepend(vignette2);
        logo.src = "https://fungi-fungus.github.io/lets-freak.gif";
        logo.style.filter = "none";
        logo.style.width = "max-content";
        logo.style.maxWidth = "none";
        // Source - https://stackoverflow.com/a/46259996
        // Posted by alessandrio, modified by community. See post 'Timeline' for change history
        // Retrieved 2026-10-11, License - CC BY-SA 3.0

        //first select the container
        function freakyClass(){
            var container = website,
                //then all nodes
                elems = container.getElementsByTagName("*"),
                len = elems.length,
                elem,
                elemText,
                i,
                //we assign unnecessary elements
                unwanted = ["script", "img", "input"];
            //a normal loop
            for(i=0;i<len;i+=1){
              elem = elems[i];
              //pay attention here
              //if the element does not have children it means that it will only contain text
              if(unwanted.indexOf(elem.nodeName.toLowerCase())=="-1"){
                if(!elem.children.length){
                  //you also have to check that the text exists
                  elemText = elem.innerText;
                  if(elemText){
                    //and finally
                    elem.classList.add("fungifungus-freaky");
                  }
                }
              }
            }
        };
        freakyClass();
        observer = new MutationObserver(function(){
            freakyClass();
        });
        observer.observe(website, {
            childList:true,subtree:true,characterData:true
        });
    };
    if (toggle) freak();
  //settings
    if (website.querySelector("#settings-dangers")){
        const freakysetting = document.createElement("div");
        freakysetting.classList.add("settings-preference");
        freakysetting.innerHTML = `<div class=settings-preference-info><h3 class=settings-title style=font-family:Papyrus,PapyrusPlain,fantasy>freaky mode👅💦</h3><p class=settings-description>freaky mode</p></div><label class="lb-checkbox setting-toggle-box-checkbox"><input class=lb-checkbox-input id=fungifungus-freakyswitch type=checkbox></label>`
        website.querySelector("#settings-dangers").append(freakysetting);
        const freakswitch = website.querySelector("#fungifungus-freakyswitch");
        if (toggle) {
            freakswitch.setAttribute("checked", "")
        };
        freakswitch.addEventListener("click", () => {
            if (!toggle) {
                localStorage.setItem("fungifungus-freaky", "true");
                freak();
                togg();
            } else {
                localStorage.setItem("fungifungus-freaky", "false");
                observer.disconnect();
                observer = null;
                vignette1.remove();
                vignette2.remove();
                freakystyle.remove();
                freakystyle = null;
                document.querySelectorAll(".fungifungus-freaky").forEach((e) => e.classList.remove("fungifungus-freaky"));
                logo.src = "https://static.darflen.com/img/logo.svg";
                logo.removeAttribute("style");
                togg();
            };
        });
    };
})();